let deals=[],preview=false,savedOnly=false,query='',sortOrder='feed',activeFilter='all',toastTimer,feedFailed=false,feedLoading=false,feedGeneration=0;
const SAVED_KEY='fluqon.saved.v1',grid=document.querySelector('#deals');
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function readSaved(){try{const value=JSON.parse(localStorage.getItem(SAVED_KEY)||'[]');return new Set(Array.isArray(value)?value.filter(id=>typeof id==='string'&&/^[a-z0-9][a-z0-9-]{2,59}$/.test(id)).slice(0,300):[]);}catch{return new Set();}}
let saved=readSaved();
function notify(message){const toast=document.querySelector('#toast');clearTimeout(toastTimer);toast.textContent=message;toast.classList.add('visible');toastTimer=setTimeout(()=>toast.classList.remove('visible'),5000);}
function toggleSaved(id){if(!deals.some(d=>d.id===id))return;const removing=saved.has(id);if(removing)saved.delete(id);else saved.add(id);let stored=true;try{localStorage.setItem(SAVED_KEY,JSON.stringify([...saved]));}catch{stored=false;}render();notify(stored?(removing?'Removed from saved offers.':'Saved on this device.'):'Browser storage unavailable. Saved list lasts for this visit.');(grid.querySelector(`[data-save="${id}"]`)||document.querySelector('#saved-filter')).focus();}
function filtered(){const result=deals.filter(d=>(activeFilter==='all'||(activeFilter==='glitch'?d.glitch:d.category===activeFilter))&&(!savedOnly||saved.has(d.id))&&(!query||[d.retailer,d.department,d.title,d.description,d.code].join(' ').toLocaleLowerCase('en-AU').includes(query)));if(sortOrder==='retailer')result.sort((a,b)=>a.retailer.localeCompare(b.retailer,'en-AU'));if(sortOrder==='title')result.sort((a,b)=>a.title.localeCompare(b.title,'en-AU'));return result;}
function render(){
 const visible=filtered();document.querySelector('#saved-count').textContent=String(saved.size);document.querySelector('#saved-filter').setAttribute('aria-pressed',String(savedOnly));document.querySelector('#empty').textContent=feedFailed&&!preview?'The checked feed could not load. Use retry.feed_ to try again.':deals.length===0&&!preview?'No checked offers published yet. We would rather show an empty feed than a made-up deal.':savedOnly?'No available offers in your saved list.':'No offers match. Try a different search or filter.';document.querySelector('#feed-status').textContent=feedLoading?'Loading checked offers…':feedFailed&&!preview?'The checked feed is unavailable. Retry loading offers.':visible.length+(preview?' sample offers.':' checked offers.');const retry=document.querySelector('#feed-retry');if(retry){retry.hidden=!feedFailed;retry.disabled=feedLoading;}document.querySelector('#result-count').textContent=String(visible.length).padStart(2,'0')+' SIGNALS';document.querySelector('#empty').hidden=visible.length>0;
 grid.innerHTML=visible.map(d=>`<article class="card ${d.glitch?'glitch':''}" aria-labelledby="title-${d.id}"><div class="card-top"><span>${esc(d.retailer)} // ${esc(d.department)}</span><span class="index">${String(deals.indexOf(d)+1).padStart(2,'0')}</span></div><h3 id="title-${d.id}">${esc(d.title)}</h3><p class="card-description">${esc(d.description)}</p><div class="offer-line"><span class="discount">${esc(d.discount)}</span>${preview?`<span class="price">${d.was?`<del>${esc(d.was)}</del>`:''}${esc(d.now)}</span>`:''}</div><div class="code-row"><span class="coupon-code" id="code-${d.id}">${esc(d.code||'NO CODE NEEDED')}</span><button class="copy" data-copy="${d.id}" aria-label="${d.code?'Copy code and open':'Open'} ${esc(d.retailer)}">${d.code?'COPY CODE':'OPEN OFFER'} <span aria-hidden="true">↗</span></button></div>${!preview?`${d.referralBeneficiary?`<p class="referral-disclosure">Who benefits: ${esc(d.referralBeneficiary)}. ${esc(d.referralReward)}</p>`:''}<p class="live-conditions">${esc(d.conditions)}</p>${d.affiliate?'<p class="live-conditions">Affiliate link. We may earn a commission.</p>':''}`:''}<div class="card-bottom"><span class="status"><span class="dot"></span>${preview?'Sample · unchecked':d.checkMethod==='checkout'?'Checkout checked':'Merchant confirmed'}${!preview?` <time class="data" datetime="${esc(d.checkedAt)}">${esc(new Intl.DateTimeFormat('en-AU',{timeZone:'Australia/Melbourne',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(d.checkedAt)))}</time>`:''}</span>${!preview?`<a class="report" href="/report?offer=${d.id}">Report Patched</a>`:'<span class="report">Demo only</span>'}</div><div class="deal-share"><button type="button" class="share-link" data-save="${d.id}" aria-pressed="${saved.has(d.id)}">${saved.has(d.id)?'saved.fluq_':'save.fluq_'}</button><button type="button" class="share-link" data-share-site data-share-url="/s/${esc(d.shortSlug)}" data-share-title="${esc(d.title)}">share.fluq_</button>${!preview?`<a href="/offers/${d.id}">Details ↗</a><a href="/contribute?offer=${d.id}">edit.fluq_</a><a href="/history?offer=${d.id}">history.fluq_</a>`:''}</div></article>`).join('');
}
function setFilter(filter){activeFilter=filter;document.querySelectorAll('.filter').forEach(b=>{const active=b.dataset.filter===filter;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});render();}
async function loadFeed(manual=false){const generation=++feedGeneration;const restoreRetryFocus=manual&&document.activeElement===document.querySelector('#feed-retry');if(preview){feedFailed=false;feedLoading=false;deals=sampleDeals;render();return;}feedLoading=true;render();try{const response=await fetch('/api/offers',{cache:'no-store'});if(!response.ok)throw Error();const data=await response.json();if(generation!==feedGeneration)return;deals=data.offers.filter(d=>/^[a-z0-9][a-z0-9-]{2,59}$/.test(d.id)&&typeof d.url==='string'&&d.url.startsWith('https://'));feedFailed=false;document.querySelector('#feed-note-copy').textContent='Only published offers with a current check appear here. Prices can change; read the conditions and check your checkout.';}catch{if(generation!==feedGeneration)return;deals=[];feedFailed=true;document.querySelector('#feed-note-copy').textContent='The feed is temporarily unavailable. Please try again shortly.';}finally{if(generation===feedGeneration){feedLoading=false;render();if(restoreRetryFocus&&document.activeElement===document.body)(feedFailed?document.querySelector('#feed-retry'):document.querySelector('#offer-search')).focus({preventScroll:true});}}}
document.querySelector('#feed-retry')?.addEventListener('click',()=>void loadFeed(true));
document.querySelectorAll('.filter').forEach(b=>b.addEventListener('click',()=>setFilter(b.dataset.filter)));
grid.addEventListener('click',async event=>{const save=event.target.closest('[data-save]');if(save)toggleSaved(save.dataset.save);const button=event.target.closest('[data-copy]');if(!button)return;const d=deals.find(d=>d.id===button.dataset.copy);if(!d)return;window.open(d.url,'_blank','noopener,noreferrer');if(!d.code)return;try{await navigator.clipboard.writeText(d.code);button.textContent='COPIED!';notify(preview?'Sample code copied. This offer is unverified.':'Code copied. Check the merchant’s conditions.');setTimeout(()=>{if(button.isConnected)button.textContent='COPY CODE ↗';},2200);}catch{const range=document.createRange();range.selectNodeContents(document.querySelector('#code-'+d.id));const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);notify('Code selected. Copy it manually.');}});
document.querySelector('#preview-toggle').addEventListener('click',()=>{preview=!preview;document.querySelector('.system').lastChild.textContent=preview?'SYSTEM: PREVIEW MODE':'SYSTEM: CHECKED FEED';document.querySelector('.sample-tag').textContent=preview?'DEMO DATA':'CHECKED FEED';document.querySelector('#preview-toggle').setAttribute('aria-pressed',String(preview));document.querySelector('#preview-toggle').textContent=preview?'Show live feed':'preview.fluq_';document.querySelector('#feed-note-copy').textContent=preview?'Sample offers only. These codes and prices are unverified.':'Loading the checked feed…';void loadFeed();});
document.querySelector('#offer-search').addEventListener('input',event=>{query=event.target.value.trim().toLocaleLowerCase('en-AU');render();});document.querySelector('#offer-sort').addEventListener('change',event=>{sortOrder=event.target.value;render();});document.querySelector('#saved-filter').addEventListener('click',()=>{savedOnly=!savedOnly;render();});window.addEventListener('storage',event=>{if(event.key===SAVED_KEY||event.key===null){saved=readSaved();render();}});
function updateClock(){const now=new Date();const clock=document.querySelector('#clock');clock.textContent=new Intl.DateTimeFormat('en-AU',{timeZone:'Australia/Melbourne',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23',timeZoneName:'short'}).format(now);clock.dateTime=now.toISOString();}render();void loadFeed();updateClock();setInterval(updateClock,1000);setInterval(()=>void loadFeed(),60000);
